(
    (
        page.status_code = 'SCHEDULED'
        AND page.publish_start_dttm <= #{currentDttm}
        AND (
            page.publish_end_dttm IS NULL
            OR page.publish_end_dttm > #{currentDttm}
        )
    )
    OR (
        page.status_code = 'PUBLISHED'
        AND (
            page.publish_start_dttm IS NULL
            OR page.publish_start_dttm <= #{currentDttm}
        )
        AND (
            page.publish_end_dttm IS NULL
            OR page.publish_end_dttm > #{currentDttm}
        )
    )
    OR page.status_code IN ('ENDED', 'CANCELLED', 'ARCHIVED')
)

