    performance_project_id, entry_policy, late_entry_policy,
    recording_policy, cancellation_policy,
    accessibility_policy, directions, parking_information
) VALUES (
    #{performanceProjectId}, #{entryPolicy}, #{lateEntryPolicy},
    #{recordingPolicy}, #{cancellationPolicy},
    #{accessibilityPolicy}, #{directions}, #{parkingInformation}
)
